package com.lqq.supportflow.eventing.infrastructure.persistence;
import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper; import com.baomidou.mybatisplus.core.conditions.update.UpdateWrapper; import com.lqq.supportflow.eventing.domain.*; import java.time.Instant; import java.util.List; import org.springframework.stereotype.Component;
@Component public class MyBatisOutboxAdapter implements OutboxPort { private final OutboxMapper mapper; public MyBatisOutboxAdapter(OutboxMapper mapper){this.mapper=mapper;} public void record(Long tenantId,String eventType,String aggregateType,String aggregateId,String payload){OutboxEntity entity=new OutboxEntity();entity.tenantId=tenantId;entity.eventType=eventType;entity.aggregateType=aggregateType;entity.aggregateId=aggregateId;entity.payload=payload;entity.status="PENDING";entity.attemptCount=0;entity.createdAt=Instant.now();mapper.insert(entity);} public List<OutboxEvent> pending(int limit){return mapper.selectList(new QueryWrapper<OutboxEntity>().eq("status","PENDING").orderByAsc("created_at").last("LIMIT "+limit)).stream().map(entity->new OutboxEvent(entity.id,entity.tenantId,entity.eventType,entity.aggregateType,entity.aggregateId,entity.payload,entity.createdAt)).toList();} public void markPublished(Long eventId){mapper.update(new OutboxEntity(),new UpdateWrapper<OutboxEntity>().eq("id",eventId).eq("status","PENDING").set("status","PUBLISHED").set("published_at",Instant.now()).setSql("attempt_count = attempt_count + 1"));}}
